# zipkin-instrumentation-hapi

A hapi middleware that adds Zipkin tracing to the application.

## Usage

```javascript
const Hapi = require('hapi');
const {Tracer, ExplicitContext, ConsoleRecorder} = require('zipkin');
const zipkinMiddleware = require('zipkin-instrumentation-hapi').hapiMiddleware;

const ctxImpl = new ExplicitContext();
const recorder = new ConsoleRecorder();

const localServiceName = 'service-a'; // name of this application
const tracer = new Tracer({ctxImpl, recorder, localServiceName});

const server = new Hapi.Server();

// Add the Zipkin middleware
server.register({
  register: zipkinMiddleware,
  options: {tracer}
});
```

const TraceId = require('../src/tracer/TraceId');
const {Span, Endpoint} = require('../src/model');
const {Some} = require('../src/option');

describe('Endpoint setters', () => {
  // Zipkin does this, so doing so early alerts users
  it('should lowercase serviceName', () => {
    const endpoint = new Endpoint({
      serviceName: 'Unknown'
    });
    expect(endpoint.serviceName).to.equal('unknown');
  });
});

describe('Span setters', () => {
  // Zipkin does this, so doing so early alerts users
  it('should lowercase name', () => {
    const span = new Span(new TraceId({
      traceId: new Some('a'),
      spanId: 'b',
    }));
    span.setName('StarWars');
    expect(span.name).to.equal('starwars');
  });

  // otherwise people can't find their spans
  it('span.setLocalEndpoint() should accept unknown serviceName', () => {
    const span = new Span(new TraceId({
      traceId: new Some('a'),
      spanId: 'b',
    }));
    span.setLocalEndpoint(new Endpoint({
      serviceName: 'unknown'
    }));
    expect(span.localEndpoint.serviceName).to.equal('unknown');
  });

  it('should not set empty endpoints', () => {
    const span = new Span(new TraceId({
      traceId: new Some('a'),
      spanId: 'b',
    }));
    span.setLocalEndpoint(new Endpoint({}));
    span.setRemoteEndpoint(new Endpoint({}));

    expect(span.localEndpoint).to.equal(undefined);
    expect(span.remoteEndpoint).to.equal(undefined);
  });

  it('should set minimum duration of 1 microsecond', () => {
    const span = new Span(new TraceId({
      traceId: new Some('a'),
      spanId: 'b',
    }));
    span.setDuration(0.77);

    expect(span.duration).to.equal(1);
  });
});

const sinon = require('sinon');
const {Tracer, ExplicitContext} = require('zipkin');
const Hapi = require('hapi');
const middleware = require('../src/hapiMiddleware');

describe('hapi middleware - integration test', () => {
  it('should receive trace info from the client', done => {
    const record = sinon.spy();
    const recorder = {record};
    const ctxImpl = new ExplicitContext();
    const tracer = new Tracer({recorder, ctxImpl});

    ctxImpl.scoped(() => {
      const server = new Hapi.Server();
      server.connection();
      server.route({
        method: 'POST',
        path: '/foo',
        config: {
          handler: (request, reply) => {
            reply({status: 'OK'}).code(202);
          }
        }
      });
      server.register({
        register: middleware,
        options: {tracer, serviceName: 'service-a'}
      });

      const method = 'POST';
      const url = '/foo';
      const headers = {
        'X-B3-TraceId': 'aaa',
        'X-B3-SpanId': 'bbb',
        'X-B3-Flags': '1'
      };
      server.inject({method, url, headers}, () => {
        const annotations = record.args.map((args) => args[0]);

        annotations.forEach((ann) => expect(ann.traceId.traceId).to.equal('aaa'));
        annotations.forEach((ann) => expect(ann.traceId.spanId).to.equal('bbb'));

        expect(annotations[0].annotation.annotationType).to.equal('ServiceName');
        expect(annotations[0].annotation.serviceName).to.equal('service-a');

        expect(annotations[1].annotation.annotationType).to.equal('Rpc');
        expect(annotations[1].annotation.name).to.equal(method);

        expect(annotations[2].annotation.annotationType).to.equal('BinaryAnnotation');
        expect(annotations[2].annotation.key).to.equal('http.path');
        expect(annotations[2].annotation.value).to.equal(url);

        expect(annotations[3].annotation.annotationType).to.equal('ServerRecv');

        expect(annotations[4].annotation.annotationType).to.equal('LocalAddr');

        expect(annotations[5].annotation.annotationType).to.equal('BinaryAnnotation');
        expect(annotations[5].annotation.key).to.equal('http.status_code');
        expect(annotations[5].annotation.value).to.equal('202');

        expect(annotations[6].annotation.annotationType).to.equal('ServerSend');

        done();
      });
    });
  });

  it('should not crash on 404', done => {
    const record = sinon.spy();
    const recorder = {record};
    const ctxImpl = new ExplicitContext();
    const tracer = new Tracer({recorder, ctxImpl});

    ctxImpl.scoped(() => {
      const server = new Hapi.Server();
      server.connection();
      server.register({
        register: middleware,
        options: {tracer, serviceName: 'service-a'}
      });

      const method = 'POST';
      const url = '/foo';
      server.inject({method, url}, () => {
        const annotations = record.args.map((args) => args[0]);
        expect(annotations[5].annotation.annotationType).to.equal('BinaryAnnotation');
        expect(annotations[5].annotation.key).to.equal('http.status_code');
        expect(annotations[5].annotation.value).to.equal('404');
        done();
      });
    });
  });

  it('should properly report the URL with a query string', done => {
    const record = sinon.spy();
    const recorder = {record};
    const ctxImpl = new ExplicitContext();
    const tracer = new Tracer({recorder, ctxImpl});

    ctxImpl.scoped(() => {
      const server = new Hapi.Server();
      server.connection();
      server.route({
        method: 'GET',
        path: '/foo',
        config: {
          handler: (request, reply) => {
            reply({status: 'OK'}).code(202);
          }
        }
      });
      server.register({
        register: middleware,
        options: {tracer, serviceName: 'service-a'}
      });

      const method = 'GET';
      const path = '/foo';
      const url = `${path}?abc=123`;
      server.inject({method, url}, () => {
        const annotations = record.args.map(args => args[0]);

        expect(annotations[2].annotation.annotationType).to.equal('BinaryAnnotation');
        expect(annotations[2].annotation.key).to.equal('http.path');
        expect(annotations[2].annotation.value).to.equal(path);

        done();
      });
    });
  });

  it('should record a reasonably accurate span duration', done => {
    const record = sinon.spy();
    const recorder = {record};
    const ctxImpl = new ExplicitContext();
    const tracer = new Tracer({recorder, ctxImpl});
    const PAUSE_TIME_MILLIS = 100;

    ctxImpl.scoped(() => {
      const server = new Hapi.Server();
      server.connection();
      server.route({
        method: 'POST',
        path: '/foo',
        config: {
          handler: (request, reply) => {
            setTimeout(() => reply({status: 'OK'}).code(202), PAUSE_TIME_MILLIS);
          }
        }
      });

      server.register({
        register: middleware,
        options: {tracer, serviceName: 'service-a'}
      });

      const method = 'POST';
      const url = '/foo';

      server.inject({method, url}, () => {
        const annotations = record.args.map((args) => args[0]);
        const serverRecvTs = annotations[3].timestamp / 1000.0;
        const serverSendTs = annotations[6].timestamp / 1000.0;
        const durationMillis = (serverSendTs - serverRecvTs);

        expect(durationMillis).to.be.greaterThan(PAUSE_TIME_MILLIS);

        done();
      });
    });
  });
});

const lolex = require('lolex');
const ExplicitContext = require('../src/explicit-context.js');

describe('ExplicitContext', () => {
  it('should start with context null', () => {
    const ctx = new ExplicitContext();
    expect(ctx.getContext()).to.equal(null);
  });

  it('should set an inner context', () => {
    const ctx = new ExplicitContext();
    ctx.letContext('foo', () => {
      expect(ctx.getContext()).to.equal('foo');
    });
  });

  it('should return the inner value', () => {
    const ctx = new ExplicitContext();
    const returnValue = ctx.letContext('foo', () => 123);
    expect(returnValue).to.equal(123);
  });

  it('should be reset after the callback', () => {
    const ctx = new ExplicitContext();
    ctx.letContext('foo', () => {
      // do nothing
    });
    expect(ctx.getContext()).to.equal(null);
  });

  it('support nested contexts', () => {
    const ctx = new ExplicitContext();
    const finalReturnValue = ctx.letContext('foo', () => {
      expect(ctx.getContext()).to.equal('foo');
      const innerReturnValue = ctx.letContext('bar', () => {
        expect(ctx.getContext()).to.equal('bar');
        return 1;
      });
      expect(ctx.getContext()).to.equal('foo');
      return innerReturnValue + 2;
    });
    expect(ctx.getContext()).to.equal(null);
    expect(finalReturnValue).to.equal(3);
  });

  it('does not support async context', done => {
    const clock = lolex.install();

    const ctx = new ExplicitContext();
    function callback() {
      expect(ctx.getContext()).to.equal(null);
      done();
    }
    ctx.letContext('foo', () => {
      setTimeout(callback, 10);
    });

    clock.tick(10);
    clock.uninstall();
  });
});

# zipkin-instrumentation-postgres

This library will wrap the [pg client](https://www.npmjs.com/package/pg).

## Usage

```javascript
const {Tracer} = require('zipkin');
const Postgres = require('pg');
const zipkinClient = require('zipkin-instrumentation-postgres');

const tracer = new Tracer({ctxImpl, recorder}); // configure your tracer properly here

const ZipkinPostgres = zipkinClient(tracer, Postgres);

const connectionOptions = {
  user: 'postgres',
  password: 'secret',
  host: 'localhost',
  database: 'mydb'
};

const client = new ZipkinPostgres.Client(connectionOptions);
const pool = new ZipkinPostgres.Pool(connectionOptions);

// Your application code here
client.query('SELECT NOW()', (err, result) => {
  console.log(err, result);
});

pool.query('SELECT NOW()')
  .then(console.log)
  .catch(console.error);
```

# zipkin-instrumentation-redis

This library will wrap the [redis client](https://www.npmjs.com/package/redis).

## Usage

```javascript
const {Tracer} = require('zipkin');
const Redis = require('redis');
const zipkinClient = require('zipkin-instrumentation-redis');
const localServiceName = 'service-a'; // name of this application
const tracer = new Tracer({ctxImpl, recorder, localServiceName});
const redisConnectionOptions = {
  host: 'localhost',
  port: '6379'
};
const redis = zipkinClient(tracer, Redis, redisConnectionOptions);

// Your application code here
redis.get('foo', (err, data) => {
  console.log('got', data.foo);
});
```

