const sinon = require('sinon');
const {Tracer, ExplicitContext, BatchRecorder} = require('zipkin');
const zipkinClient = require('../src/zipkinClient');

const postgresConnectionOptions = {
  host: '127.0.0.1',
  port: 5432,
  database: 'postgres',
  user: 'postgres',
  password: process.env.POSTGRES_PWD
};

const Postgres = require('pg');

function getPostgres(tracer) {
  return zipkinClient(tracer, Postgres);
}

function expectCorrectSpanData(span) {
  expect(span.name).to.equal(`query ${postgresConnectionOptions.database}`);
  expect(span.localEndpoint.serviceName).to.equal('unknown');
  expect(span.remoteEndpoint.serviceName).to.equal('postgres');
  expect(span.remoteEndpoint.ipv4).to.equal(postgresConnectionOptions.host);
  expect(span.remoteEndpoint.port).to.equal(postgresConnectionOptions.port);
}

describe('postgres interceptor', () => {
  it('should add zipkin annotations', (done) => {
    const logSpan = sinon.spy();

    const ctxImpl = new ExplicitContext();
    const recorder = new BatchRecorder({logger: {logSpan}});
    const tracer = new Tracer({ctxImpl, recorder});
    tracer.setId(tracer.createRootId());

    const postgres = new (getPostgres(tracer).Client)(postgresConnectionOptions);
    postgres.connect();
    postgres.query('SELECT NOW()', () => {
      postgres.query('SELECT NOW()').then(() => {
        const query = new Postgres.Query('SELECT NOW()');
        const result = postgres.query(query);
        result.on('end', () => {
          const spans = logSpan.args.map(arg => arg[0]);
          expect(spans).to.have.length(3);
          spans.forEach(expectCorrectSpanData);

          done();
        });
      });
    });
  });

  it('should annotate pool', (done) => {
    const logSpan = sinon.spy();

    const ctxImpl = new ExplicitContext();
    const recorder = new BatchRecorder({logger: {logSpan}});
    const tracer = new Tracer({ctxImpl, recorder});
    tracer.setId(tracer.createRootId());

    const postgres = new (getPostgres(tracer).Pool)(postgresConnectionOptions);
    postgres.connect();
    postgres.query('SELECT NOW()', () => {
      postgres.query('SELECT NOW()').then(() => {
        const spans = logSpan.args.map(arg => arg[0]);
        expect(spans).to.have.length(2);
        spans.forEach(expectCorrectSpanData);

        done();
      });
    });
  });

  it('should annotate postgres errors', (done) => {
    const logSpan = sinon.spy();

    const ctxImpl = new ExplicitContext();
    const recorder = new BatchRecorder({logger: {logSpan}});
    const tracer = new Tracer({ctxImpl, recorder});
    tracer.setId(tracer.createRootId());

    const postgres = new (getPostgres(tracer).Client)(postgresConnectionOptions);
    postgres.connect();

    postgres.query('INVALID QUERY', (firstError) => {
      postgres.query('ERROR QUERY').catch((secondError) => {
        const query = new Postgres.Query('FAILED QUERY()');
        const result = postgres.query(query);
        result.on('error', (thirdError) => {
          const errorTags = logSpan.args.map(arg => arg[0].tags.error);
          expect(errorTags[0]).to.equal(firstError.toString());
          expect(errorTags[1]).to.equal(secondError.toString());
          expect(errorTags[2]).to.equal(thirdError.toString());
        });

        done();
      });
    });
  });

  it('should run postgres calls', (done) => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: sinon.spy()};
    const tracer = new Tracer({ctxImpl, recorder});
    tracer.setId(tracer.createRootId());

    const postgres = new (getPostgres(tracer).Client)(postgresConnectionOptions);
    postgres.connect();

    const queryText = 'SELECT $1::text as "res"';
    const queryValues = ['test'];
    postgres.query(queryText, queryValues, (error, firstResult) => {
      postgres.query({text: queryText, values: queryValues}).then((secondResult) => {
        const query = new Postgres.Query(queryText, queryValues);
        const result = postgres.query(query);

        expect(query).to.equal(result);

        const submittableRows = [];
        query.on('row', (row) => submittableRows.push(row));
        query.on('end', () => {
          expect(firstResult.rows[0].res).to.equal('test');
          expect(secondResult.rows[0].res).to.equal('test');
          expect(submittableRows[0].res).to.equal('test');

          done();
        });
      });
    });
  });
});

const sinon = require('sinon');
const {Tracer, ExplicitContext} = require('zipkin');
const zipkinClient = require('../src/zipkinClient');

const redisConnectionOptions = {
  host: 'localhost',
  port: '6379'
};

const Redis = require('redis');

function getRedis(tracer) {
  return zipkinClient(tracer, Redis, redisConnectionOptions);
}

function expectAnnotationsDescribeRedisInteraction(annotations) {
  const sn = annotations[1].annotation;
  expect(sn.annotationType).to.equal('ServiceName');
  expect(sn.serviceName).to.equal('unknown');

  const sa = annotations[2].annotation;
  expect(sa.annotationType).to.equal('ServerAddr');
  expect(sa.serviceName).to.equal('redis');
  expect(sa.host.addr).to.equal(redisConnectionOptions.host);
  expect(sa.port).to.equal(redisConnectionOptions.port);
}

function expectAnnotationsBelongToTheSameSpan(annotations) {
  let lastSpanId;
  annotations.forEach((ann) => {
    if (!lastSpanId) {
      lastSpanId = ann.traceId.spanId;
    }
    expect(ann.traceId.spanId).to.equal(lastSpanId);
  });
}

function runTest(annotations) {
  expectAnnotationsDescribeRedisInteraction(annotations);
  expectAnnotationsBelongToTheSameSpan(annotations);
}

describe('redis interceptor', () => {
  it('should add zipkin annotations', (done) => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: sinon.spy()};
    // const recorder = new ConsoleRecorder();
    const tracer = new Tracer({ctxImpl, recorder});

    const redis = getRedis(tracer);
    redis.on('error', done);
    tracer.setId(tracer.createRootId());
    redis.set('ping', 'pong', 10, () => {
      redis.get('ping', () => {
        const annotations = recorder.record.args.map(args => args[0]);
        const firstAnn = annotations[0];
        expect(annotations).to.have.length(10);

        // we expect two spans, run annotations tests for each

        runTest(annotations.slice(0, annotations.length / 2));
        runTest(annotations.slice(annotations.length / 2, annotations.length));

        expect(
          annotations[0].traceId.spanId
        ).not.to.equal(annotations[annotations.length / 2].traceId.spanId);

        annotations.forEach(ann => {
          expect(ann.traceId.parentId).to.equal(firstAnn.traceId.traceId);
          expect(ann.traceId.spanId).not.to.equal(firstAnn.traceId.traceId);
          expect(ann.traceId.traceId).to.equal(firstAnn.traceId.traceId);
        });

        done();
      });
    });
  });

  it('should add zipkin annotations for batch method', (done) => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: sinon.spy()};
    // const recorder = new ConsoleRecorder();
    const tracer = new Tracer({ctxImpl, recorder});

    const redis = getRedis(tracer);
    redis.on('error', done);
    tracer.setId(tracer.createRootId());
    redis.set('ping', 'pong', 10, () => {
      redis.batch([['get', 'ping']]).exec(() => {
        const annotations = recorder.record.args.map(args => args[0]);
        const firstAnn = annotations[0];
        expect(annotations).to.have.length(11);
        expect(annotations[5].annotation.key).to.equal('commands');
        expect(annotations[5].annotation.value).to.deep.equal('[["get","ping"]]');
        expect(annotations[6].annotation.name).to.equal('exec');

        // we expect two spans, run annotations tests for each
        expectAnnotationsBelongToTheSameSpan(
          annotations.slice(0, annotations.length / 2));
        expectAnnotationsDescribeRedisInteraction(
          annotations.slice(0, annotations.length / 2));

        expectAnnotationsBelongToTheSameSpan(
          annotations.slice(annotations.length / 2, annotations.length));
        expectAnnotationsDescribeRedisInteraction(
          annotations.slice(annotations.length / 2 + 1, annotations.length));

        expect(
          annotations[0].traceId.spanId
        ).not.to.equal(annotations[Math.floor(annotations.length / 2)].traceId.spanId);

        annotations.forEach(ann => {
          expect(ann.traceId.parentId).to.equal(firstAnn.traceId.traceId);
          expect(ann.traceId.spanId).not.to.equal(firstAnn.traceId.traceId);
          expect(ann.traceId.traceId).to.equal(firstAnn.traceId.traceId);
        });

        done();
      });
    });
  });

  it('should add zipkin annotations for multiple embedded methods', (done) => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: sinon.spy()};
    // const recorder = new ConsoleRecorder();
    const tracer = new Tracer({ctxImpl, recorder});

    const redis = getRedis(tracer);
    redis.on('error', done);
    tracer.setId(tracer.createRootId());
    redis.set('ping', 'pong', 10, () => {
      redis.batch([['get', 'ping']]).exec(() => {
        redis.multi([['get', 'ping']]).exec(() => {
          redis.get('ping', () => {
            const annotations = recorder.record.args.map(args => args[0]);
            const firstAnn = annotations[0];
            annotations.forEach(ann => {
              expect(ann.traceId.parentId).to.equal(firstAnn.traceId.traceId);
              expect(ann.traceId.traceId).to.equal(firstAnn.traceId.traceId);
              expect(ann.traceId.spanId).not.to.equal(firstAnn.traceId.traceId);
            });
            done();
          });
        });
      });
    });
  });

  it('should run redis calls', done => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: () => { }};
    const tracer = new Tracer({ctxImpl, recorder});
    const redis = getRedis(tracer);
    redis.on('error', done);
    redis.set('foo', 'bar', err => {
      if (err) {
        done(err);
      } else {
        redis.get('foo', (err2, data) => {
          if (err2) {
            done(err2);
          } else {
            expect(data).to.deep.equal('bar');
            done();
          }
        });
      }
    });
  });
});

const spawn = require('child_process').spawn;
const path = require('path');
const sinon = require('sinon');
const {Tracer, ExplicitContext} = require('zipkin');
const zipkinClient = require('../src/zipkinClient');

const memcachedConnectionOptions = {
  timeout: 1000,
  idle: 1000,
  failures: 0,
  retries: 0,
  poolsize: 1
};

const Memcached = require('memcached');

function getMemcached(tracer) {
  const host = process.env.MEMCACHED_HOST || 'localhost:11211';
  console.log(`Connecting to Memcached on host ${host}`);
  return new (zipkinClient(tracer, Memcached))(host, memcachedConnectionOptions);
}

describe('memcached interceptor', () => {
  let memcachedProcess;

  before(function(done) {
    try {
      const isWindows = /^win/.test(process.platform);
      if (isWindows) {
        console.log('Running tests on a windows box; try to spawn a memcached process.');
        memcachedProcess = spawn(path.join(__dirname, 'windows', 'memcached.exe'), [], {
          cwd: path.join(__dirname, 'windows')
        });

        memcachedProcess.stdout.on('data', (data) => {
          console.log(`memcached stdout: ${data}`);
        });

        memcachedProcess.stderr.on('data', (data) => {
          console.log(`memcached stderr: ${data}`);
        });

        // give it 10 seconds to boot
        setTimeout(done, 10000);
        this.timeout(15000);
      } else {
        done();
      }
    } catch (err) {
      console.error('The before hook failed.', err);
      done(err);
    }
  });

  after(() => {
    if (memcachedProcess) {
      memcachedProcess.kill();
    }
  });

  it('should add zipkin annotations', (done) => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: sinon.spy()};
    // const recorder = new ConsoleRecorder();
    const tracer = new Tracer({ctxImpl, recorder});

    const memcached = getMemcached(tracer);
    memcached.on('error', done);
    tracer.setId(tracer.createRootId());
    const ctx = ctxImpl.getContext();
    memcached.set('ping', 'pong', 10, () => {
      ctxImpl.letContext(ctx, () => {
        memcached.get('ping', () => {
          const annotations = recorder.record.args.map(args => args[0]);
          const firstAnn = annotations[0];

          expect(annotations).to.have.length(12);

          function runTest(start, stop) {
            const spanAnnotations = annotations.slice(start, stop);

            const sn = spanAnnotations[1].annotation;
            expect(sn.annotationType).to.equal('ServiceName');
            expect(sn.serviceName).to.equal('unknown');

            const sa = spanAnnotations[4].annotation;
            expect(sa.annotationType).to.equal('ServerAddr');
            expect(sa.serviceName).to.equal('memcached');

            let lastSpanId;
            spanAnnotations.forEach((ann) => {
              if (!lastSpanId) {
                lastSpanId = ann.traceId.spanId;
              }
              expect(ann.traceId.spanId).to.equal(lastSpanId);
            });
          }

          // we expect two spans, run annotations tests for each
          runTest(0, annotations.length / 2);
          runTest(annotations.length / 2, annotations.length);

          expect(
            annotations[0].traceId.spanId
          ).not.to.equal(annotations[annotations.length / 2].traceId.spanId);

          annotations.forEach(ann => {
            expect(ann.traceId.parentId).to.equal(firstAnn.traceId.traceId);
            expect(ann.traceId.spanId).not.to.equal(firstAnn.traceId.traceId);
            expect(ann.traceId.traceId).to.equal(firstAnn.traceId.traceId);
          });

          done();
        });
      });
    });
  });

  it('should run memcached calls', done => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: () => { }};
    const tracer = new Tracer({ctxImpl, recorder});
    const memcached = getMemcached(tracer);
    memcached.on('error', done);
    memcached.set('foo', 'bar', 10, err => {
      if (err) {
        done(err);
      } else {
        memcached.getMulti(['foo', 'fox'], (err2, data) => {
          if (err2) {
            done(err2);
          } else {
            expect(data).to.deep.equal({foo: 'bar'});
            done();
          }
        });
      }
    });
  });

  it('should restore original trace ID', done => {
    const ctxImpl = new ExplicitContext();
    const recorder = {record: () => { }};
    const tracer = new Tracer({ctxImpl, recorder});
    const fakeID = tracer.createRootId();
    tracer.setId(fakeID);
    const memcached = getMemcached(tracer);
    memcached.on('error', done);
    memcached.set('scooby', 'doo', 10, () => {
      expect(tracer.id.traceId).to.equal(fakeID.traceId);
      memcached.get('scooby', (err, data) => {
        expect(tracer.id.traceId).to.equal(fakeID.traceId);
        expect(data).to.equal('doo');
        done();
      });
    });
  });
});

